//! Smoke test for `generate_v1` (cell E1). Constructs a minimal IR
//! `Module` by hand (one feature, no kinds), runs the emitter, and
//! verifies the structural invariants the proposal locks in:
//!
//! 1. At least one feature `.gen.go` plus the root `go.mod`.
//! 2. `go.mod` carries the resolved module path and the
//!    `require lazuli.dev/runtime/lazuli <version>` line.
//! 3. Each `.gen.go` opens with the Code Connect-style banner
//!    (`// Code generated by lazuli; DO NOT EDIT.`) and a
//!    matching `package <feature_name>` directive.
//!
//! Hand-rolled IR (not via the analyzer) keeps the test
//! deliberately decoupled from grammar-side drift.

use std::collections::BTreeMap;

use lazuli_analyzer::source_map::SourceMapResolver;
use lazuli_codegen_go::{
    generate_v1, generate_v1_with_manifest, generate_v1_with_manifest_and_source, GoEmitOptions,
    GoSourceContext, LazuriteDev, LazuriteGenerateGo, LazuriteManifest, LazuritePlugin,
    LAZULI_GO_VERSION,
};
use lazuli_ir::{
    AppLocale, AppLogging, AppManifest, AppTracing, Assignment, BuiltinType, Command,
    CommandEffect, CommandInput, CommandKind, CreateEffect, Defaults, EnumDecl, EnumVariant, Expr,
    Feature, Field, FieldConstraints, Module, Path, Policies, PolicyRef, QualifiedName, Resource,
    SourceMap, SpanRef, StorageValue, TypeRef, TypedSlot,
};

